// Combines the webhook payload, service, business settings, and existing
// bookings to decide whether the requested slot can be booked.
// Returns { isAvailable, startTime, endTime, timezone } for the IF node below.
//
// TIMEZONE FIX (Follow-Up Refinement Milestone): the previous version built
// `new Date(\`${date}T${time}:00\`)`, which JS parses as either local-server
// time or UTC depending on runtime, ignoring the customer's actual selected
// timezone entirely. That produced a wrong absolute instant for every
// customer not in the server's own zone, which then propagated into the
// saved booking, the Google Calendar event, and both emails.
//
// This now interprets date+time as wall-clock time IN the customer's
// selected IANA zone (body.booking.timezone) and converts it to a correct
// UTC instant, using only built-in Intl (no external timezone library).

const body = $('Webhook').first().json.body;
const service = $('Retrieve Service Details').first().json;
const settings = $('Retrieve Business Settings').first().json;
const existing = $input.all().map((i) => i.json);

const customerTz = body.booking.timezone || settings.timezone || 'UTC';

function zonedWallClockToUtc(dateStr, timeStr, timeZone) {
  // Naive guess: treat the wall-clock string as if it were UTC.
  const naiveUtc = new Date(`${dateStr}T${timeStr}:00Z`);
  // Render that same instant in the target zone and in UTC, and diff them
  // to get the zone's real offset at that moment (correctly handles DST).
  const inZone = new Date(naiveUtc.toLocaleString('en-US', { timeZone }));
  const inUtc = new Date(naiveUtc.toLocaleString('en-US', { timeZone: 'UTC' }));
  const offsetMs = inUtc.getTime() - inZone.getTime();
  return new Date(naiveUtc.getTime() + offsetMs);
}

const start = zonedWallClockToUtc(body.booking.date, body.booking.time, customerTz);
const end = new Date(start.getTime() + service.duration_minutes * 60000);

const bufferMs = (settings.buffer_minutes || 0) * 60000;
const leadMs = (settings.booking_lead_time_minutes || 0) * 60000;

const meetsLeadTime = start.getTime() - Date.now() >= leadMs;

const overlaps = existing.some((b) => {
  const bStart = new Date(b.start_time).getTime() - bufferMs;
  const bEnd = new Date(b.end_time).getTime() + bufferMs;
  return start.getTime() < bEnd && end.getTime() > bStart;
});

return [
  {
    json: {
      isAvailable: settings.is_accepting_bookings && meetsLeadTime && !overlaps,
      startTime: start.toISOString(),
      endTime: end.toISOString(),
      timezone: customerTz,
    },
  },
];

